# envcfg.py
import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            toml_config = tomllib.load(f)
            config.update(tomllib_config)
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_keys = key[len(env_prefix)+1:].split('__')
            current = config
            for k in nested_keys[:-1]:
                if k not in current:
                    current[k] = {}
                current = current[k]
            current[nested_keys[-1]] = _coerce(value, defaults.get(nested_keys[-1]))
    return config

def _coerce(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', '1', 'yes')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

# test_envcfg.py
import pytest
import envcfg
import os
import tomllib

def test_load_config_defaults():
    defaults = {'server': {'port': 8080}}
    config = envcfg.load_config(defaults)
    assert config == defaults

def test_load_config_toml():
    toml_content = b'[server]\nport = 8081\n'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    defaults = {'server': {'port': 8080}}
    config = envcfg.load_config(defaults, 'config.toml')
    assert config['server']['port'] == 8081

def test_load_config_env():
    os.environ['APP__SERVER__PORT'] = '8082'
    defaults = {'server': {'port': 8080}}
    config = envcfg.load_config(defaults, env_prefix='APP')
    assert config['server']['port'] == 8082

def test_load_config_coerce_int():
    os.environ['APP__SERVER__PORT'] = '8083'
    defaults = {'server': {'port': 8080}}
    config = envcfg.load_config(defaults, env_prefix='APP')
    assert isinstance(config['server']['port'], int)

def test_load_config_coerce_float():
    os.environ['APP__SERVER__FLOAT'] = '3.14'
    defaults = {'server': {'float': 3.1415}}
    config = envcfg.load_config(defaults, env_prefix='APP')
    assert isinstance(config['server']['float'], float)

def test_load_config_coerce_bool():
    os.environ['APP__SERVER__BOOL'] = 'true'
    defaults = {'server': {'bool': False}}
    config = envcfg.load_config(defaults, env_prefix='APP')
    assert isinstance(config['server']['bool'], bool)

def test_load_config_error_missing_default():
    os.environ['APP__SERVER__PORT'] = '8084'
    with pytest.raises(envcfg.ConfigError):
        envcfg.load_config({}, env_prefix='APP')

def test_load_config_error_invalid_type():
    os.environ['APP__SERVER__PORT'] = 'invalid'
    defaults = {'server': {'port': 8080}}
    with pytest.raises(envcfg.ConfigError):
        envcfg.load_config(defaults, env_prefix='APP')

